import os
import sys
import unittest

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")


class Tests(unittest.TestCase):
    def test_vendor_zones_are_standard(self):
        known = set(open(os.path.join(ROOT, "tests", "known_zones.txt")).read().split())
        for zone in open(os.path.join(ROOT, "vendor", "zones.txt")).read().split():
            self.assertIn(zone, known)


if __name__ == "__main__":
    unittest.main()
